styles.css:
position: relative;
overflow: hidden;
isolation: isolate;
--ls-home-hero-surface: var(--wp--custom--color--surface--canvas);
--ls-home-hero-brand: var(--wp--custom--color--effect--hero--brand);
--ls-home-hero-cta: var(--wp--custom--color--effect--hero--cta);
--ls-home-hero-accent: var(--wp--custom--color--effect--hero--accent);
background:
	radial-gradient(circle at 16% 14%, color-mix(in srgb, var(--ls-home-hero-brand) 12%, transparent) 0%, transparent 34%),
	radial-gradient(circle at 84% 18%, color-mix(in srgb, var(--ls-home-hero-cta) 14%, transparent) 0%, transparent 28%),
	radial-gradient(circle at 50% 100%, color-mix(in srgb, var(--ls-home-hero-accent) 7%, transparent) 0%, transparent 36%),
	linear-gradient(180deg, color-mix(in srgb, var(--ls-home-hero-surface) 98%, var(--wp--custom--color--surface--highlight) 2%) 0%, var(--ls-home-hero-surface) 100%);

& > :not(.ls-home-hero-section__background) {
	position: relative;
	z-index: var(--wp--custom--z-index--content);
}

& .ls-home-hero-section__background {
	position: absolute;
	inset: 0;
	pointer-events: none;
	overflow: hidden;
	z-index: var(--wp--custom--z-index--base);
}

& .ls-home-hero-section__network {
	position: absolute;
	inset: 0;
	pointer-events: none;
	overflow: hidden;
	z-index: var(--wp--custom--z-index--content);
	opacity: 0.92;
}

& .ls-home-hero-section__orb {
	position: absolute;
	border-radius: 999px;
	filter: blur(80px);
	opacity: 0.8;
	transform: translate3d(0, 0, 0);
	will-change: transform;
	z-index: var(--wp--custom--z-index--base);
}

& .ls-home-hero-section__orb--brand {
	top: 8%;
	left: -8rem;
	width: 24rem;
	height: 24rem;
	background: color-mix(in srgb, var(--ls-home-hero-brand) 24%, transparent);
}

& .ls-home-hero-section__orb--cta {
	right: -6rem;
	bottom: 10%;
	width: 20rem;
	height: 20rem;
	background: color-mix(in srgb, var(--ls-home-hero-cta) 22%, transparent);
}

& .ls-home-hero-section__canvas {
	display: block;
	inline-size: 100%;
	block-size: 100%;
}

& .wp-block-heading {
	overflow-wrap: anywhere;
}
